import*as THREE from'three';import{materials}from'../../core/index.js';import{addCadParts}from'../../modeling/cad.js';import{mesh,slab,screw,portQuaternion}from'../../modeling/parts.js';import data from'./geometry-data.js';import{grove,terminal}from'./connectors.js';import{JumperPort}from'./Shunt.js';import{spec,jumperPositions}from'./dimensions.js';import{addStickers}from'./stickers.js';
const tau=Math.PI*2;function hole(s,x,y,r){const p=new THREE.Path();p.absarc(x,y,r,0,tau,false);s.holes.push(p);}function extrude(parent,s,depth,p,m,n){return mesh(parent,new THREE.ExtrudeGeometry(s,{depth,bevelEnabled:false,curveSegments:48}),m,p,n);}
function board(host){const s=new THREE.Shape();s.moveTo(-10.4,-24);s.lineTo(-8.8,-26);s.lineTo(-5.5,-26);s.lineTo(-5.5,-20.2);s.lineTo(5.5,-20.2);s.lineTo(5.5,-26);s.lineTo(8.8,-26);s.lineTo(10.4,-24);s.lineTo(10.4,-19.6);s.lineTo(8,-19.6);s.absarc(8,-16,3.6,-Math.PI/2,-Math.PI*1.5,true);s.lineTo(10.4,-12.4);s.lineTo(10.4,24.3);s.lineTo(8.5,26.3);s.lineTo(-8.5,26.3);s.lineTo(-10.4,24.3);s.lineTo(-10.4,-12.4);s.lineTo(-8,-12.4);s.absarc(-8,-16,3.6,Math.PI/2,-Math.PI/2,true);s.lineTo(-10.4,-19.6);s.closePath();hole(s,0,-16,2.1);const pcb=extrude(host.body,s,.8,[0,0,-.8],materials.plastic(0x202821,{roughness:.88}),'AIN4-20mA fixed PCB with genuine mounting reliefs and retaining bore');pcb.userData.role='physical-pcb';const metal=materials.metal(0xb6bba9,{roughness:.49}),dark=materials.plastic(0x21241f,{roughness:.86}),ceramic=materials.plastic(0xaaa07b,{roughness:.86}),packages=[];const ic=(x,y,w,h,depth,n,leads)=>{const body=slab(host.body,w,h,depth,.13,[x,y,.08],dark,[],.02);body.name='AIN4-20mA '+n;packages.push(body);for(const sign of[-1,1])for(let i=0;i<leads;i++)mesh(host.body,new THREE.BoxGeometry(.8,.27,.16),metal,[x+sign*(w/2+.25),y+(i-(leads-1)/2)*.55,.18],n+' physical lead');return body;};const mcu=ic(-3.9,-6.5,4.4,6.2,1,'U14 STM32G030F6P6 fixed package',10),isolator=ic(0,2.6,6.5,9.5,2.7,'U1 HCNR200 isolation package',4),amplifiers=[ic(-6.7,7.9,1.8,2.9,.9,'U2 SGM321 fixed amplifier',3),ic(6.7,-1.5,1.8,2.9,.9,'U3 SGM321 fixed amplifier',3)];const passives=[];for(const[i,x,y]of[[1,-8,10],[2,-8,12.3],[3,8,10.8],[4,8,8.5],[5,6.4,3.4],[6,6.4,5.6],[7,-6.7,3.4],[8,-6.7,.9],[9,4.5,-8.3],[10,6.8,-8.3],[11,8.7,-5.3],[12,-8.3,-3.1],[13,0,-10.3],[14,-2.3,10.2],[15,.2,10.2],[16,2.7,10.2]]){passives.push(mesh(host.body,new THREE.BoxGeometry(1.6,.9,.7),i<5?dark:ceramic,[x,y,.4],'AIN4-20mA fixed capacitor resistor package '+i));for(const sign of[-1,1])mesh(host.body,new THREE.BoxGeometry(.28,.9,.72),metal,[x+sign*.66,y,.4],'AIN4-20mA passive solder termination');}ic(-5.8,-11,1.8,2.9,.9,'U15 HX6306 fixed regulator',3);ic(6.8,13,1.8,2.9,.9,'Q1 transistor fixed package',3);const pads=[];for(let i=0;i<5;i++){const shape=new THREE.Shape();shape.absarc(0,0,.55,0,tau,false);pads.push(extrude(host.body,shape,.035,[-4+i*1.75,-21.5,.005],materials.metal(0xc6a947,{roughness:.51}),'AIN4-20mA concealed J2 SWD pad '+(i+1)));}return{pcb,mcu,isolator,amplifiers,packages,passives,pads};}
function headers(host){const black=materials.plastic(0x161916,{roughness:.8}),gold=materials.metal(0xb9a45b,{roughness:.43});const p2=mesh(host.body,new THREE.BoxGeometry(10.16,2.54,2),black,[0,spec.header.p2Y,1],'AIN4-20mA exposed P2 four-pin header insulator'),p3=mesh(host.body,new THREE.BoxGeometry(5.08,2.54,2),black,[0,spec.header.p3Y,1],'AIN4-20mA exposed P3 two-pin header insulator'),pins=[];for(const[id,[x,y]]of Object.entries(spec.header.pins)){pins.push(mesh(host.body,new THREE.BoxGeometry(.64,.64,6.7),gold,[x,y,2.75],`AIN4-20mA true fixed header pin ${id}`));}const ports=[];for(const item of jumperPositions){const[a,b]=item.pins.map(p=>spec.header.pins[p]),position=[(a[0]+b[0])/2,(a[1]+b[1])/2,spec.header.pinZ],q=portQuaternion('front');if(a[0]===b[0])q.premultiply(new THREE.Quaternion().setFromAxisAngle(new THREE.Vector3(0,0,1),Math.PI/2));ports.push(host.add(new JumperPort({id:item.id,label:item.pins.join(' — '),connector:'pin-header-2.54-2p',position,quaternion:q,hitSize:[5.08,.8,2.3],pins:item.pins.map((name,i)=>({n:i+1,name})),pinGrid:{cols:2,rows:1,pitch:2.54,center:[0,0],order:col=>2-col},meta:{role:'visual-connector',face:'front',physicalPins:item.pins,scope:'Physical two-pin cap position only;shared physical pins reject overlapping caps.No source selection,power,current,conductivity,firmware or sensor state'}})));}return{p2,p3,pins,ports};}
export function buildAIN420mA(host,options={}){const parts=addCadParts(host,data,{shell:materials.plastic(0xe9eae5,{roughness:.78})}),pcb=board(host),input=grove(host),output=terminal(host),jumpers=headers(host),fixing=screw(host.body,[0,-16,-3.01],'back',1.55);fixing.name='AIN4-20mA fixed recessed rear hex retaining screw';fixing.traverse(o=>{if(o.isMesh)o.name='AIN4-20mA fixed hex retaining screw face';});mesh(host.body,new THREE.CylinderGeometry(.65,.65,3.5,32).rotateX(Math.PI/2),materials.metal(0x9ca093),[0,-16,-1.2],'AIN4-20mA concealed fixed screw shank');const frontCarrier=slab(host.body,16.2,23.5,.1,.04,[0,-.25,3.8],materials.plastic(0xd5dcd5,{roughness:.86}),[],.005);frontCarrier.name='AIN4-20mA physical front adhesive label substrate over native supporting rails';const backCarrier=slab(host.body,16.2,36.8,.1,.04,[0,6.4,-4],materials.plastic(0xd5dcd5,{roughness:.86}),[],.005);backCarrier.name='AIN4-20mA physical rear adhesive label substrate';host.ain420maAssembly={parts,pcb,input,output,jumpers,fixing,frontCarrier,backCarrier};host.unitStickers=addStickers(host);if(options.covers===false){for(const p of Object.values(parts))p.visible=false;frontCarrier.visible=false;backCarrier.visible=false;}}
